using namespace std;

struct Node {
    int x;
    int dec;
    // 大根堆：减少量大的优先
    bool operator < (const Node& other) const {
        return dec < other.dec;
    }
};

long long solve(int n, int k, vector<int>& a) {
    int mx = *max_element(a.begin(), a.end());

    // 最小基除数（最小素因子）筛
    vector<int> spf(mx + 1);
    for (int i = 0; i <= mx; i++) {
        spf[i] = i;
    }
    for (int i = 2; i * i <= mx; i++) {
        if (spf[i] == i) {          // i 是素数（基除数）
            for (int j = i * i; j <= mx; j += i) {
                if (spf[j] == j) {
                    spf[j] = i;
                }
            }
        }
    }

    long long total = 0;
    for (int x : a) total += x;

    priority_queue<Node> pq;

    for (int x : a) {
        if (x > 1) {
            int p = spf[x];
            int dec = x - x / p;
            pq.push({x, dec});
        }
    }

    for (int i = 0; i < k; i++) {
        if (pq.empty()) break;
        Node cur = pq.top();
        pq.pop();

        total -= cur.dec;                 // 减去本次减少量
        int nx = cur.x / spf[cur.x];      // 基除后的新值

        if (nx > 1) {
            int p = spf[nx];
            int dec = nx - nx / p;
            pq.push({nx, dec});
        }
    }

    return total;
}

